const raw = $input.first().json.data || $input.first().json.body || $input.first().json.response || '';

function parseCsv(text) {
  const rows = [];
  let row = [];
  let field = '';
  let inQuotes = false;
  for (let i = 0; i < text.length; i++) {
    const char = text[i];
    const next = text[i + 1];
    if (char === '"') {
      if (inQuotes && next === '"') {
        field += '"';
        i++;
      } else {
        inQuotes = !inQuotes;
      }
    } else if (char === ',' && !inQuotes) {
      row.push(field);
      field = '';
    } else if ((char === '\n' || char === '\r') && !inQuotes) {
      if (char === '\r' && next === '\n') i++;
      row.push(field);
      if (row.some((value) => value !== '')) rows.push(row);
      row = [];
      field = '';
    } else {
      field += char;
    }
  }
  if (field || row.length) {
    row.push(field);
    rows.push(row);
  }
  return rows;
}

const parsed = parseCsv(raw);
if (parsed.length < 2) {
  return [{ json: { status: 'ERROR', message: 'No CSV data returned. Check Google Sheets sharing: Anyone with link should be Viewer.' } }];
}

const headers = parsed[0];
const records = parsed.slice(1).map((row) => Object.fromEntries(headers.map((header, index) => [header, row[index] || ''])));
const areas = [...new Set(records.map((record) => record.Area).filter(Boolean))];

const summary = areas.map((area) => {
  const areaRows = records.filter((record) => record.Area === area);
  const top = areaRows.find((record) => Number(record.Rank) === 1) || areaRows[0];
  return {
    area,
    topRestaurant: top['Restaurant Name'],
    googleRating: top['Google Rating'],
    wongnaiRating: top['Wongnai Rating'],
    evidenceStatus: top['Evidence Status'],
    recommendationCount: areaRows.length,
  };
});

return [{
  json: {
    status: 'OK',
    workflowPurpose: 'Automation evidence for Q3 AI Food Assistant',
    totalRestaurantsRead: records.length,
    areasCovered: areas.length,
    summary,
    note: 'This workflow reads Final_Top3 from Google Sheets and automatically summarizes the best restaurant per area.'
  }
}];
